Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module RlLia.
Import Ltac2.Ltac2 Ltac2.Constr.

Ltac2 rl_named (s : string) (b : binder) : bool :=
  match Binder.name b with
  | Some id => String.equal (Ident.to_string id) s
  | None => false
  end.

Ltac2 rec rl_imem (x : int) (l : int list) : bool :=
  match l with
  | [] => false
  | y :: r => if Int.equal x y then true else rl_imem x r
  end.

Ltac2 rl_frees (c : constr) : int list :=
  let acc := Ref.ref [] in
  let rec go (n : int) (c : constr) :=
    match Unsafe.kind c with
    | Unsafe.Rel k =>
      if Int.gt k n then
        (let j := Int.sub k n in if rl_imem j (Ref.get acc) then () else Ref.set acc (j :: Ref.get acc))
      else ()
    | _ => Unsafe.iter_with_binders (fun n _ => Int.add n 1) go n c
    end in
  go 0 c;
  Ref.get acc.

Ltac2 rl_ren (f : int -> int) (c : constr) : constr :=
  let rec go (n : int) (c : constr) :=
    match Unsafe.kind c with
    | Unsafe.Rel k => if Int.gt k n then Unsafe.make (Unsafe.Rel (Int.add n (f (Int.sub k n)))) else c
    | _ => Unsafe.map_with_binders (fun n _ => Int.add n 1) go n c
    end in
  go 0 c.

Ltac2 rl_fail (m : string) := Control.throw (Tactic_failure (Some (Message.of_string m))).

Ltac2 rec rl_zeta (ctx : (binder * constr option) list) (c : constr) : constr option :=
  match rl_frees c with
  | [] => Some c
  | fs =>
    let mx := List.fold_left (fun a j => if Int.gt j a then j else a) 0 fs in
    let ok := Ref.ref true in
    let sub := List.map (fun j =>
      if Bool.and (Ref.get ok) (rl_imem j fs) then
        match List.nth ctx (Int.sub j 1) with
        | (_, Some v) =>
          (match rl_zeta (List.skipn j ctx) v with
           | Some v => v
           | None => Ref.set ok false; 'True
           end)
        | _ => Ref.set ok false; 'True
        end
      else 'True) (List.init mx (fun i => Int.add i 1)) in
    if Ref.get ok then Some (Unsafe.substnl sub 0 c) else None
  end.

Ltac2 rl_ok (t : constr) (v : constr) : bool :=
  let probe := Unsafe.make (Unsafe.App (Unsafe.make (Unsafe.Lambda (Binder.unsafe_make None Binder.Relevant t) 'I)) [| v |]) in
  match Unsafe.check probe with
  | Val _ => true
  | Err _ => false
  end.

Ltac2 rec rl_natoms (t : constr) : int :=
  match Unsafe.kind t with
  | Unsafe.Prod b body =>
    let ty := Binder.type b in
    let isat := match Unsafe.kind ty with Unsafe.Sort _ => true | _ => Constr.equal ty 'Z end in
    if isat then Int.add 1 (rl_natoms body) else 0
  | _ => 0
  end.

Ltac2 rec rl_peel (n : int) (t : constr) : constr :=
  if Int.equal n 0 then t else
  match Unsafe.kind t with
  | Unsafe.Prod _ b => rl_peel (Int.sub n 1) b
  | _ => rl_fail "RlLia: peel"
  end.

Ltac2 rl_findname (w : string) (ctx : (binder * constr option) list) : int option :=
  let rec go (i : int) (l : (binder * constr option) list) :=
    match l with
    | [] => None
    | (b, _) :: r => if rl_named w b then Some i else go (Int.add i 1) r
    end in
  go 1 ctx.

Ltac2 rec rl_ins (x : int) (l : int list) : int list :=
  match l with
  | [] => [x]
  | y :: r => if Int.gt x y then x :: l else y :: rl_ins x r
  end.

Ltac2 rec rl_pos (x : int) (l : int list) (k : int) : int :=
  match l with
  | [] => rl_fail "RlLia: closure"
  | y :: r => if Int.equal x y then k else rl_pos x r (Int.add k 1)
  end.

Ltac2 rl_hole (want : string list) (hs : evar list ref) (ctx : (binder * constr option) list) (t : constr) (args : constr array) : constr :=
  let al := Array.to_list args in
  let na := rl_natoms t in
  let ninst := if Int.lt na (List.length al) then na else List.length al in
  let g := Unsafe.substnl (List.rev (List.firstn ninst al)) 0 (rl_peel ninst t) in
  let rest := List.skipn ninst al in
  let chosen := List.fold_left (fun acc w => match rl_findname w ctx with
                                             | Some i => if rl_imem i acc then acc else i :: acc
                                             | None => acc end) [] want in
  let need := Ref.ref [] in
  let rec add (is : int list) :=
    match is with
    | [] => ()
    | i :: r =>
      if rl_imem i (Ref.get need) then add r else
      (Ref.set need (i :: Ref.get need);
       let (b, _) := List.nth ctx (Int.sub i 1) in
       add (List.append (List.map (fun j => Int.add i j) (rl_frees (Binder.type b))) r))
    end in
  add (List.append (rl_frees g) chosen);
  let idx := List.fold_left (fun acc i => rl_ins i acc) [] (Ref.get need) in
  let r := List.length idx in
  let bs := List.mapi (fun k0 i =>
      let k := Int.add k0 1 in
      let (b, _) := List.nth ctx (Int.sub i 1) in
      let ty := rl_ren (fun j => Int.sub k (rl_pos (Int.add i j) idx 1)) (Binder.type b) in
      let nm := match Binder.name b with
                | Some id =>
                  if rl_imem i chosen then Some id
                  else if List.exist (fun w => String.equal w (Ident.to_string id)) want then None
                  else Some id
                | None => None
                end in
      Binder.unsafe_make nm (Binder.relevance b) ty) idx in
  let g := rl_ren (fun j => Int.sub (Int.add r 1) (rl_pos j idx 1)) g in
  let ty := List.fold_left (fun acc b => Unsafe.make (Unsafe.Prod b acc)) g (List.rev bs) in
  let h := open_constr:(_ : $ty) in
  let h := match Unsafe.kind h with Unsafe.Cast h' _ _ => h' | _ => h end in
  (match Unsafe.kind h with
   | Unsafe.Evar e _ => Ref.set hs (e :: Ref.get hs)
   | _ => rl_fail "RlLia: hole"
   end);
  match List.append (List.map (fun i => Unsafe.make (Unsafe.Rel i)) idx) rest with
  | [] => h
  | xs => Unsafe.make (Unsafe.App h (Array.of_list xs))
  end.

Ltac2 rl_bmap (f : constr -> constr) (b : binder) : binder :=
  Binder.unsafe_make (Binder.name b) (Binder.relevance b) (f (Binder.type b)).

Ltac2 rec rl_assoc (l : int) (ar : (int * constr) list) : constr option :=
  match ar with
  | [] => None
  | (k, t) :: r => if Int.equal k l then Some t else rl_assoc l r
  end.

Ltac2 rec rl_phfind (c : constr) (args : constr array) (ph : (int * evar * constr) list) : (int * constr) option :=
  match ph with
  | [] => None
  | (i, e, b) :: r => if Constr.equal c (Unsafe.make (Unsafe.Evar e args)) then Some (i, b) else rl_phfind c args r
  end.

Ltac2 rec rl_walk (want : string list) (hs : evar list ref) (cnt : int ref) (ph : (int * evar * constr) list) (inl : int list ref)
    (lvl : int) (ctx : (binder * constr option) list) (ar : (int * constr) list) (c : constr) : constr :=
  let w := rl_walk want hs cnt ph inl in
  match Unsafe.kind c with
  | Unsafe.Evar _ args =>
    (match rl_phfind c args ph with
     | Some (i, b) => Ref.set inl (i :: Ref.get inl); w lvl ctx ar b
     | None => Unsafe.map (w lvl ctx ar) c
     end)
  | Unsafe.Rel k =>
    (match rl_assoc (Int.add (Int.sub lvl k) 1) ar with
     | Some t => rl_hole want hs ctx t Array.empty
     | None => c
     end)
  | Unsafe.App f args =>
    let args := Array.map (w lvl ctx ar) args in
    (match Unsafe.kind f with
     | Unsafe.Rel k =>
       (match rl_assoc (Int.add (Int.sub lvl k) 1) ar with
        | Some t => rl_hole want hs ctx t args
        | None => Unsafe.make (Unsafe.App f args)
        end)
     | _ => Unsafe.make (Unsafe.App (w lvl ctx ar f) args)
     end)
  | Unsafe.Lambda b body =>
    Unsafe.make (Unsafe.Lambda (rl_bmap (w lvl ctx ar) b) (w (Int.add lvl 1) ((b, None) :: ctx) ar body))
  | Unsafe.Prod b body =>
    Unsafe.make (Unsafe.Prod (rl_bmap (w lvl ctx ar) b) (w (Int.add lvl 1) ((b, None) :: ctx) ar body))
  | Unsafe.LetIn b v body =>
    let t := Binder.type b in
    let broken :=
      if Bool.and (rl_named "__arith" b) (Unsafe.is_closed t) then
        match rl_zeta ctx v with
        | Some v' => if rl_ok t v' then false else true
        | None => false
        end
      else false in
    if broken then
      (Ref.set cnt (Int.add (Ref.get cnt) 1);
       let b2 := Binder.unsafe_make (Binder.name b) Binder.Relevant 'True in
       Unsafe.make (Unsafe.LetIn b2 'I (w (Int.add lvl 1) ((b2, Some 'I) :: ctx) ((Int.add lvl 1, t) :: ar) body)))
    else
      Unsafe.make (Unsafe.LetIn (rl_bmap (w lvl ctx ar) b) (w lvl ctx ar v) (w (Int.add lvl 1) ((b, Some v) :: ctx) ar body))
  | Unsafe.Fix st i bs bodies =>
    let bs' := Array.map (rl_bmap (w lvl ctx ar)) bs in
    let (lvl2, ctx2) := List.fold_left (fun (l, cx) b => (Int.add l 1, (b, None) :: cx)) (lvl, ctx) (Array.to_list bs) in
    Unsafe.make (Unsafe.Fix st i bs' (Array.map (w lvl2 ctx2 ar) bodies))
  | Unsafe.CoFix i bs bodies =>
    let bs' := Array.map (rl_bmap (w lvl ctx ar)) bs in
    let (lvl2, ctx2) := List.fold_left (fun (l, cx) b => (Int.add l 1, (b, None) :: cx)) (lvl, ctx) (Array.to_list bs) in
    Unsafe.make (Unsafe.CoFix i bs' (Array.map (w lvl2 ctx2 ar) bodies))
  | _ => Unsafe.map (w lvl ctx ar) c
  end.

Ltac2 rl_close (facts : (unit -> constr) list) (i : int) : unit :=
  Control.plus
    (fun () =>
       ltac1:(intros);
       List.iter (fun f => Control.plus (fun () => let p := f () in ltac1:(p |- pose proof p) (Ltac1.of_constr p))
                                        (fun _ => ())) facts;
       ltac1:(lia))
    (fun _ =>
       let g := Control.goal () in
       Control.throw (Tactic_failure (Some (Message.concat (Message.of_string "RlLia: hole ")
         (Message.concat (Message.of_int i) (Message.concat (Message.of_string " not proved: ") (Message.of_constr g))))))).

Ltac2 run2 (tab : string) (secs : string list) (s : string) (want : string list) (facts : (unit -> constr) list) : unit :=
  KReplay.kr_revert ();
  let ph := Ref.ref [] in
  let c := KReplay.decode_ph (Some ph) tab (KReplay.kr_secs secs) s in
  let hs := Ref.ref [] in
  let cnt := Ref.ref 0 in
  let phl := List.mapi (fun i (e, b) => (i, e, b)) (Ref.get ph) in
  let inl := Ref.ref [] in
  let c := rl_walk want hs cnt phl inl 0 [] [] c in
  Std.exact_no_check c;
  List.iter (fun (i, e, b) =>
    Control.new_goal e;
    if rl_imem i (Ref.get inl) then Control.enter (fun () => Std.exact_no_check 'I)
    else Control.enter (fun () => Std.exact_no_check (rl_walk want hs cnt phl inl 0 [] [] b))) phl;
  Message.print (Message.concat (Message.of_string "RlLia: stale certificates ")
    (Message.concat (Message.of_int (Ref.get cnt)) (Message.concat (Message.of_string ", holes ")
    (Message.concat (Message.of_int (List.length (Ref.get hs))) (Message.concat (Message.of_string ", inlined placeholders ")
    (Message.of_int (List.length (Ref.get inl))))))));
  let n := Ref.ref 0 in
  List.iter (fun e => Ref.set n (Int.add (Ref.get n) 1); let i := Ref.get n in
              Control.new_goal e; Control.enter (fun () => rl_close facts i)) (List.rev (Ref.get hs)).
End RlLia.

